contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address _logger, bytes32 _txid) public payable {
        require(_logger != address(0));
        // fresh deployment: nobody is an approved logger yet
        bool beforeApproved = c.approvedToLog(_logger); if (__ESBMC_reverted()) return;
        bool r1 = c.logRedeemed(_txid); if (__ESBMC_reverted()) return;
        bool approvedAfterFail = c.approvedToLog(_logger); if (__ESBMC_reverted()) return;
        // non-owner (this test contract) cannot approve a logger
        bool reverted;
        c.setApprovedLogger(_logger, true); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        bool stillApproved = c.approvedToLog(_logger); if (__ESBMC_reverted()) return;
        bool r2 = c.logRedeemed(_txid); if (__ESBMC_reverted()) return;
        assert(
            reverted &&
            !beforeApproved && !approvedAfterFail && !stillApproved &&
            r1 == false && r2 == false
        );
    }
    receive() external payable {}
}

